CREATE TABLE "NotificationDelivery" ("id" TEXT NOT NULL,"alertId" TEXT NOT NULL,"userId" TEXT NOT NULL,"channel" TEXT NOT NULL,"status" TEXT NOT NULL,"provider" TEXT,"externalId" TEXT,"error" TEXT,"attemptedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"deliveredAt" TIMESTAMP(3),CONSTRAINT "NotificationDelivery_pkey" PRIMARY KEY ("id"));CREATE UNIQUE INDEX "NotificationDelivery_alertId_channel_key" ON "NotificationDelivery"("alertId","channel");CREATE INDEX "NotificationDelivery_userId_attemptedAt_idx" ON "NotificationDelivery"("userId","attemptedAt");